public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    // Base case: 0 triangles divide the plane into 1 region
    if (N == 0) {
        return 1;
    }
    // Base case: 1 triangle divides the plane into 2 regions
    if (N == 1) {
        return 2;
    }
    // Base case: 2 triangles can divide the plane into 8 regions
    if (N == 2) {
        return 8;
    }
    // General formula: R(N) = R(N-1) + 2*(N-1)
    // This formula is derived from the observation that each new triangle can intersect
    // all previous triangles, adding 2 regions for each intersection plus the new region it creates
    int regions = 2; // Starting with 1 triangle
    for (int i = 2; i <= N; i++) {
        regions += 2 * (i - 1);
    }
    return regions;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles, just the plane itself
    }
    // The formula to find the maximum number of regions with N triangles
    // is derived from the fact that each new triangle can intersect all
    // previous triangles, creating new regions.
    // The formula is: R(N) = 2 * N^2 + 2 * N + 1
    return 2 * N * N + 2 * N + 1;
}

