public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    Map<Integer, Integer> frequencyMap = new HashMap<>();
    for (int number : numbers) {
        frequencyMap.put(number, frequencyMap.getOrDefault(number, 0) + 1);
    }

    int count = 0;
    for (int number : numbers) {
        int doubleValue = number * 2;
        if (frequencyMap.containsKey(doubleValue)) {
            if (doubleValue == number) {
                // If the number is zero or the number is doubled to itself, we need at least two occurrences
                if (frequencyMap.get(doubleValue) > 1) {
                    count++;
                    frequencyMap.put(doubleValue, frequencyMap.get(doubleValue) - 2);
                }
            } else {
                count++;
                frequencyMap.put(doubleValue, frequencyMap.get(doubleValue) - 1);
            }
        }
    }

    return count;
}

