public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        if (path.length == 2) {
            int x = path[0];
            int y = path[1];
            if (x >= 0 && x < n * n && y >= 0 && y < n * n) {
                pathSet.add(x + "-" + y);
            }
        }
    }

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] direction : directions) {
            int newX = current[0] + direction[0];
            int newY = current[1] + direction[1];

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                int currentIndex = current[0] * n + current[1];
                int newIndex = newX * n + newY;

                if (pathSet.contains(currentIndex + "-" + newIndex) || pathSet.contains(newIndex + "-" + currentIndex)) {
                    queue.offer(new int[]{newX, newY});
                    visited[newX][newY] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    int[][] maze = new int[n][n];

    // Mark the paths in the maze
    for (int[] path : paths) {
        if (path.length != 4 || path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n ||
            path[2] < 0 || path[2] >= n || path[3] < 0 || path[3] >= n) {
            continue; // Skip invalid paths
        }
        maze[path[0]][path[1]] = 1;
        maze[path[2]][path[3]] = 1;
    }

    return dfs(maze, start[0], start[1], end[0], end[1], visited) ? "can be travelled" : "cannot be travelled";
}

