public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startY < 0 || endX < 0 || endY < 0 || startX >= n || startY >= n || endX >= n || endY >= n) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    return canTravel(startX, startY, endX, endY, paths, visited) ? "can be travelled" : "cannot be travelled";
}

