public static String convertDatesToWeekdays(String date) {
    if (date == null || date.length() != 10 || !date.matches("\\d{2} \\d{2} \\d{4}")) {
        return "Invalid date format. Please use 'MM dd yyyy'.";
    }

    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    String[] months = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };

    if (month < 1 || month > 12 || day < 1 || day > 31) {
        return "Invalid date. Please enter valid month and day.";
    }

    long daysSinceEpoch = (year - 1970) * 365L + (year - 1969) / 4;
    for (int i = 1; i < month; i++) {
        if (i == 4 || i == 6 || i == 9 || i == 11) {
            daysSinceEpoch += 30;
        } else if (i == 2) {
            daysSinceEpoch += (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) ? 29 : 28;
        } else {
            daysSinceEpoch += 31;
        }
    }
    daysSinceEpoch += day - 1;

    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    int weekdayIndex = (int) ((daysSinceEpoch + 4) % 7); // 4 accounts for 1970-01-01 being a Thursday

    return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[weekdayIndex];
}

