public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int len = arr.length;
    int removeCount = len / 20; // 5% of the elements to remove from both ends

    // Sort the array
    Arrays.sort(arr);

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = removeCount; i < len - removeCount; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    int remainingElements = len - 2 * removeCount;
    return sum / remainingElements;
}

