    for (int[][] row : dp) {
        for (int[] arr : row) {
            Arrays.fill(arr, -1);
        }
    }

    dp[0][0][0] = 1;

    for (int num : nums) {
        for (int i = Math.min(n/2, totalSum / num); i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                for (int k = totalSum - num; k >= 0; k--) {
                    if (dp[i][j][k] == 1) {
                        dp[i + 1][j + 1][k + num] = 1;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int sum = 1; sum <= totalSum; sum++) {
            if (dp[i][i][sum] == 1 && sum * n == totalSum * i) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    int n = nums.length;
    for (int num : nums) {
        totalSum += num;
    }

    // dp[i][j][k] will be true if we can take j numbers from nums with sum k
    boolean[][][] dp = new boolean[n + 1][n + 1][totalSum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = i; j >= 1; j--) {
            for (int k = 0; k <= totalSum; k++) {
                if (dp[i - 1][j - 1][k] && k + num <= totalSum) {
                    dp[i][j][k + num] = true;
                }
            }
        }
        // Copy the previous state
        for (int j = 0; j <= i; j++) {
            for (int k = 0; k <= totalSum; k++) {
                dp[i][j][k] |= dp[i - 1][j][k];
            }
        }
    }

    // Check for all possible splits
    for (int i = 1; i < n; i++) {
        for (int j = 1; j <= i; j++) {
            if (totalSum * j % n == 0) {
                int requiredSum = j * totalSum / n;
                if (dp[i][j][requiredSum]) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two steps.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must have at least two elements.");
    }

    int n = cost.length;
    int[] dp = new int[n + 1];

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must have at least two elements.");
    }

    int n = cost.length;
    int first = cost[0];
    int second = cost[1];

    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
        second = current;
    }

    return Math.min(first, second);
}

