}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0) {
        return false;
    }

    int need = (1 << k); // Number of different binary strings of length k
    boolean[] seen = new boolean[need];
    int allOne = need - 1; // Binary representation of k '1's
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal & allOne) << 1) + (s.charAt(i) - '0');

        // Only consider the last k bits and make sure the length is exactly k
        if (i >= k - 1 && !seen[hashVal]) {
            seen[hashVal] = true;
            need--;
            if (need == 0) {
                return true;
            }
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    int total = 1 << k; // Total number of binary strings of length k
    boolean[] found = new boolean[total];

    int value = 0;
    int mask = total - 1; // Mask to keep only the last k bits

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & mask | (s.charAt(i) - '0');

        if (i >= k - 1 && !found[value]) {
            found[value] = true;
            total--;
            if (total == 0) {
                return true;
            }
        }
    }

    return false;
}

