public int minInsertions(String s) {
    int left = 0; // Count of '(' that needed
    int right = 0; // Count of ')' that needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            // Each '(' needs two ')'
            right += 2;
            // If we have odd right, we need to insert one ')' to make it even
            if (right % 2 == 1) {
                right--;
                left++;
            }
        } else {
            // Each ')' will reduce one needed right
            right--;
            // If we have negative right, we need to insert one '(' to balance
            if (right < 0) {
                right += 2;
                left++;
            }
        }
    }

    // The final result is the sum of left and right
    return left + right;
}

public int minInsertions(String s) {
    int open = 0; // Number of unmatched '('
    int insertions = 0; // Number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            open++;
        } else { // c == ')'
            if (open > 0) {
                open--; // Match with a previous '('
            } else {
                insertions++; // Need to insert '(' to match this ')'
            }
            // Check for consecutive '))' pattern
            if (i < s.length() - 1 && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it is already matched
            } else {
                insertions++; // Need to insert ')' to match single ')'
            }
        }
    }

    // Each remaining '(' needs one ')' to balance
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int left = 0; // Number of unmatched '('
    int right = 0; // Number of unmatched ')'

    for (char c : s.toCharArray()) {
        if (c == '(') {
            // If there is an unmatched ')', we need an insertion and match it
            if (right > 0) {
                // We need one '(' to match current ')'
                left++;
                // Now we have matched one ')'
                right--;
            }
            // Increase the count of unmatched '('
            left++;
        } else {
            // Decrease the count of unmatched '(' to match current ')'
            left--;
            // If there is no unmatched '(', we need an insertion
            if (left < 0) {
                // We need one '(' to match current ')'
                left++;
                // Increase the count of insertions
                right++;
            }
        }
    }

    // Each unmatched '(' needs a ')' and vice versa
    return left + right;
}

public int minInsertions(String s) {
    int open = 0; // Count of open parentheses needed
    int insertions = 0; // Count of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (open > 0 && open % 2 == 1) {
                // If we encounter an open parenthesis but we need a close one to balance
                insertions++; // Insert a close parenthesis
                open--; // Decrease the open count as we are balancing with an insertion
            }
            open += 2; // Increase open count by 2 for the current '('
        } else {
            open--; // Decrease open count for the current ')'
            if (open < 0) {
                // If open count goes negative, it means we need an open parenthesis
                insertions++; // Insert an open parenthesis
                open += 2; // Increase open count by 2 as we are balancing with an insertion
            }
        }
    }

    // After processing the string, any remaining open count needs to be balanced
    return insertions + open;
}

public int minInsertions(String s) {
    int open = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
            // Check for the case of "))" needing only one '('
            if (c == ')' && (s.length() > s.indexOf(c) + 1 && s.charAt(s.indexOf(c) + 1) == ')')) {
                c = ')'; // Skip the next character as it is already part of a valid pair
            } else {
                insertions++; // Need to add one ')'
            }
        }
    }

    // Add remaining required ')' for leftover '('
    insertions += open * 2;

    return insertions;
}

