public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer.");
    }

    // Generate all Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    // Now a is the largest Fibonacci number less than or equal to k
    int count = 0;
    while (k > 0) {
        k -= a;
        count++;
        // Find the largest Fibonacci number less than or equal to k
        int nextA = 1, nextB = 1;
        while (nextB <= k) {
            int nextNext = nextA + nextB;
            nextA = nextB;
            nextB = nextNext;
        }
        a = nextA;
    }

    return count;
}

