    }

    // Generate all Fibonacci numbers less than or equal to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    // Use the largest possible Fibonacci numbers to sum up to k
    while (k > 0) {
        int index = fibs.size() - 1;
        while (index >= 0 && fibs.get(index) > k) {
            index--;
        }
        k -= fibs.get(index);
        count++;
    }

    return count;
}

