        throw new IllegalArgumentException("Input values must be positive integers.");
    }

    // To store the factors
    int[] factors = new int[k];
    int count = 0;

    // Find all factors of n
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            if (count < k) {
                factors[count++] = i;
            } else {
                break;
            }
        }
    }

    // If we have less than k factors, return -1
    if (count < k) {
        return -1;
    }

    // Otherwise, return the k-th factor
    return factors[k - 1];
}

