    }

    int i = n - 1;
    while (k > 0) {
        int delta = Math.min(k, 25);
        result.setCharAt(i, (char) ('a' + delta));
        k -= delta;
        i--;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    StringBuilder result = new StringBuilder(n);
    int remainingValue = k - n; // Start by assuming all characters are 'a'

    while (remainingValue > 0) {
        int addValue = Math.min(remainingValue, 25); // Can add at most 25 to change 'a' to 'z'
        char currentChar = (char) ('a' + addValue);
        result.append(currentChar);
        remainingValue -= addValue;
        n--;
    }

    while (n > 0) {
        result.append('a');
        n--;
    }

    return result.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int currentSum = 0;
    int remainingLength = n;

    while (remainingLength > 0) {
        for (char c = 'a'; c <= 'z'; c++) {
            int currentValue = (c - 'a') + 1;
            int remainingValue = k - currentSum - currentValue;
            int remainingChars = remainingLength - 1;

            if (remainingValue >= remainingChars && remainingValue <= 26 * remainingChars) {
                result.append(c);
                currentSum += currentValue;
                remainingLength--;
                break;
            }
        }
    }

    return result.toString();
}

