public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    // Add all single digit numbers to the queue
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add(num);

        if (num == 0) continue; // Skip leading zeroes

        int lastDigit = num % 10;
        int nextNum = num * 10 + lastDigit;

        if (lastDigit > 0) {
            int smallerDigitNum = nextNum - 1;
            if (smallerDigitNum <= high) {
                queue.offer(smallerDigitNum);
            }
        }

        if (lastDigit < 9) {
            int largerDigitNum = nextNum + 1;
            if (largerDigitNum <= high) {
                queue.offer(largerDigitNum);
            }
        }
    }

    Collections.sort(result);
    return result;
}

