            result.add(num);
        }
        if (num == 0 || num > high / 10) {
            continue;
        }

        int lastDigit = num % 10;
        // Add the next possible stepping numbers
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    // Sort the result list
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Add single-digit numbers to the result if they are within the range
    for (int i = Math.max(0, low); i <= Math.min(9, high); i++) {
        result.add(i);
    }

    // Use BFS to find all stepping numbers
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();

        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add(num);
        }

        int lastDigit = num % 10;
        int nextNum1 = num * 10 + (lastDigit - 1);
        int nextNum2 = num * 10 + (lastDigit + 1);

        if (lastDigit > 0 && nextNum1 <= high) {
            queue.offer(nextNum1);
        }
        if (lastDigit < 9 && nextNum2 <= high) {
            queue.offer(nextNum2);
        }
    }

    result.sort(Integer::compareTo);
    return result;
}

