public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of the found digit that is larger than it
    int smallestIndex = i + 1;
    for (int j = i + 1; j < length; j++) {
        if (digits[j] > digits[i] && digits[j] < digits[smallestIndex]) {
            smallestIndex = j;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[smallestIndex];
    digits[smallestIndex] = temp;

    // Sort the digits after the position i in ascending order
    Arrays.sort(digits, i + 1, length);

    // Convert the character array back to an integer
    return Integer.parseInt(new String(digits));
}

