public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Create an array to store the minimum numbers of perfect squares that sum up to each number
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0; // Base case: 0 can be represented by 0 numbers

    // Precompute all perfect squares less than or equal to n
    for (int i = 1; i * i <= n; i++) {
        dp[i * i] = 1; // Perfect squares can be represented by 1 number
    }

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord);

        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        result.append(reversedWord).append(" ");
    }

    // Remove the trailing space
    return result.toString().trim();
}

